\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Venue Color Theme ──
\definecolor{primary}{HTML}{005C8A}     % Deep Cyan (UNICEF-inspired, dark for contrast)
\definecolor{secondary}{HTML}{E85D04}   % Warm Orange
\definecolor{accent}{HTML}{FFBA08}      % Amber
\definecolor{bgposter}{HTML}{F4F9FB}    % Very light cyan/blue tint
\definecolor{redbg}{HTML}{FFF8F5}       % Warm orange tint
\definecolor{bluebg}{HTML}{F0F6F9}      % Cool cyan tint
\definecolor{darkbg}{HTML}{FDF8F2}      % Warm cream tint
\definecolor{redtitlebg}{HTML}{FBEBE2}  % Card title bar backgrounds
\definecolor{bluetitlebg}{HTML}{E1ECF2}
\definecolor{darktitlebg}{HTML}{F6EFEA}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{EAF4F9}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=4pt, label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=4pt, label={\color{primary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{76}{90}\selectfont\bfseries EVERY CHILD DESERVES TO LEARN}\\[12pt]
  {\fontsize{34}{42}\selectfont Millions of children are denied their right to quality education --- UNICEF is working to change that.}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!35},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 250 million}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Out of school globally}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 70\%}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Cannot read by age 10}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 190+}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Countries with UNICEF programmes}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══

\posterbox[darkcard, title={The Global Education Crisis}
]{name=crisis, column=1, between=row5 and row9}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \begin{itemize}
    \item \textbf{Fundamental Right Denied}: Millions lack access to learning due to systemic failures.
    \item \textbf{Learning Poverty}: 70\% of children in low/middle-income nations lack basic literacy.
    \item \textbf{Lost Potential}: Enormous setbacks for communities and economies worldwide.
  \end{itemize}
}

\posterbox[redcard, title={Barriers to Education}
]{name=barriers, column=1, between=row9 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \begin{itemize}
    \item \textbf{Armed Conflict}: Schools destroyed; girls are \colorbox{secondary!20}{\textbf{2.5$\times$ more likely}} to be out of school in crisis zones.
    \vspace{6pt}
    \item \textbf{Poverty}: Families cannot afford fees; children forced into labour.
    \vspace{6pt}
    \item \textbf{Gender Inequality}: Deep social norms limit girls' access to secondary education.
    \vspace{6pt}
    \item \textbf{Disability}: \colorbox{secondary!20}{\textbf{$\sim$49\% never attend}} school in low-income countries.
    \vspace{6pt}
    \item \textbf{Climate Change}: Floods and droughts increasingly disrupt schooling for the vulnerable.
  \end{itemize}
}

% ══ COLUMN 2 ══

\posterbox[bluecard, title={UNICEF's Focus Areas}
]{name=focus, column=2, between=row5 and row15}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \begin{itemize}
    \item \textbf{Early Childhood}: Strong foundations via pre-primary education.
    \vspace{8pt}
    \item \textbf{Inclusive Education}: Ensuring disabled and marginalized groups thrive.
    \vspace{8pt}
    \item \textbf{Gender Equality}: Removing enrollment barriers for girls.
    \vspace{8pt}
    \item \textbf{Emergencies}: Learning continuity for conflict/disaster survivors.
    \vspace{8pt}
    \item \textbf{Digital Learning}: Leveraging tech to expand access and quality.
    \vspace{8pt}
    \item \textbf{Adolescent Skills}: Equipping youth for employment and civic engagement.
  \end{itemize}
}

\posterbox[highlightcard, title={What Can Be Done}
]{name=action, column=2, between=row15 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \begin{itemize}
    \item Directly supports \textbf{SDG 4}: Inclusive, equitable quality education for all.
    \vspace{8pt}
    \item Investing in education means investing in \textbf{peace, innovation, and sustainability}.
    \vspace{8pt}
    \item Intersects with child rights, protection, health, and nutrition.
    \vspace{8pt}
    \item \textbf{Together}, we can ensure that no child is left behind.
  \end{itemize}
  \vspace{16pt}
  \centering
  \colorbox{primary}{\color{white}\textbf{\fontsize{30}{36}\selectfont $\Rightarrow$ Learn more: unicef.org/education}}
}

\end{tcbposter}
\end{document}

